void verify_image_integrity(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image = NULL;
  gchar *temp_file_path = gimp_temp_name("verify_image");
  GError *error = NULL;
  gboolean success;

  /* Create the main image using the provided Gimp instance and specified flags */
  image = gimp_image_new(100, 100, GIMP_RGB);

  g_assert(image != NULL);

  /* Write the image to a temporary file */
  success = gimp_file_save(GIMP_RUN_WITH_DISPLAY, GIMP_PDB_PROC_DEFAULT, "png-save", temp_file_path, image, NULL, &error);

  g_assert(success && !error);

  /* Load the image back from the temporary file */
  success = gimp_file_load(GIMP_RUN_WITH_DISPLAY, GIMP_PDB_PROC_DEFAULT, "png-load", temp_file_path, NULL, &image, &error);

  g_assert(success && image != NULL);

  /* Clean up: delete the temporary file and release the file object */
  g_unlink(temp_file_path);
  g_free(temp_file_path);
}

void test_image_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image;
  gchar     *temp_path;
  GFile     *file;
  GError    *error = NULL;

  image = create_test_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_path = g_build_filename(g_get_tmp_dir(), "test_image.XXXXXX", NULL);
  file = g_file_new_for_path(temp_path);

  g_assert(gimp_file_save(gimp, image, temp_path, &error));
  g_assert(error == NULL);

  g_clear_error(&error);

  GimpImage *loaded_image = gimp_file_load(temp_path, &error);
  g_assert(loaded_image != NULL);
  g_assert(error == NULL);

  g_clear_error(&error);

  gimp_image_delete(image);
  gimp_image_delete(loaded_image);

  g_file_delete(file, NULL, NULL);
  g_object_unref(file);
  g_free(temp_path);
}

void verify_image_integrity(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  gchar *temp_file_path;
  GError *error = NULL;
  gboolean success;

  // Create main image
  image = gimp_image_new(...); // Assume appropriate initialization based on context

  g_assert(image != NULL);

  // Generate a temporary file path
  temp_file_path = g_strdup_printf("/tmp/test_image_%d.xcf", getpid());

  // Save the image to the temporary file
  success = gimp_file_save(gimp, image, temp_file_path, &error);
  g_assert(success && error == NULL);

  // Load the image back from the file
  GimpImage *loaded_image = gimp_file_load(gimp, temp_file_path, &error);
  g_assert(loaded_image != NULL && error == NULL);

  // Assert data integrity of the loaded image (example: compare dimensions)
  g_assert(gimp_image_get_width(image) == gimp_image_get_width(loaded_image));
  g_assert(gimp_image_get_height(image) == gimp_image_get_height(loaded_image));

  // Clean up
  g_remove(temp_file_path);
  g_free(temp_file_path);
  g_object_unref(image);
  g_object_unref(loaded_image);
}

void write_and_verify_image(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  GimpImage *image;
  gchar *temp_filename;
  GFile *temp_file;
  GError *error = NULL;
  gboolean success;

  image = gimp_image_new(gimp, 100, 100, GIMP_RGB_IMAGE, GIMP_PRECISION_U8, FALSE);
  g_return_if_fail(image != NULL);

  temp_filename = g_strdup_printf("/tmp/gimp_temp_image_%d.xcf", getpid());
  temp_file = g_file_new_for_path(temp_filename);

  success = gimp_file_save(gimp, GIMP_EXPORT_EXPORT, temp_file, image, NULL, NULL, NULL, &error);
  g_return_if_fail(success && error == NULL);

  gimp_image_delete(image);

  image = gimp_file_load(temp_file, NULL, &error);
  g_return_if_fail(image != NULL && error == NULL);

  g_object_unref(image);
  g_object_unref(temp_file);

  g_remove(temp_filename);
  g_free(temp_filename);
}

void test_image_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
